    ch.vkLabel = ch.tg ? 'Или во ВКонтакте' : 'Узнать первым во ВКонтакте';
    ch.vkStyle = 'display:flex;align-items:center;justify-content:center;text-align:center;font-family:Russo One,sans-serif;text-decoration:none;box-sizing:border-box;border:3px solid #141414;' +
      (ch.tg ? 'font-size:16px;min-height:44px;padding:8px 14px;background:#ffffff;color:#141414' : 'font-size:18px;min-height:52px;padding:12px 18px;background:#ffd60a;color:#141414;box-shadow:4px 4px 0 #141414');
    ch.note = ch.any ? 'Новые выпуски анонсируем в канале.' : '';
    const cards = list.map((a, i) => Object.assign({}, a, {
      plus: a.issue >= 8,
      accessLabel: a.issue >= 8 ? 'Новинка · CyberComics+' : 'Открыт',
      accessStyle: 'margin-left:auto;font-family:Russo One,sans-serif;font-size:12px;border:2px solid #141414;padding:1px 8px;' + (a.issue >= 8 ? 'background:#ff2e93;color:#ffffff' : 'background:#2ee59d;color:#141414'),
      district: DN[a.dist],
      href: 'Issue' + a.issue + '.dc.html',
      stars: '★'.repeat(a.diff) + '☆'.repeat(3 - a.diff),
      diffLabel: 'Сложность: ' + a.diff + ' из 3',
      bitsLabel: a.read ? '+50 ✓' : '+50 бит',
      bitsStyle: 'margin-left:auto;font-family:Russo One,sans-serif;font-size:14px;padding:2px 8px;border:2px solid #141414;background:' + (a.read ? '#ffffff' : '#2ee59d'),
      cardStyle: 'display:flex;flex-direction:column;text-decoration:none;color:#141414;background:#ffffff;border:3px solid #141414;box-shadow:6px 6px 0 #141414;transform:rotate(' + tilts[i % 3] + ')',
      art: a.art || 'v' + a.issue,
      tag: a.dist === 'base' && stepOf(a.issue) ? 'Фундамент · шаг ' + stepOf(a.issue) : (TAG[a.dist] || DN[a.dist]),
      tagStyle: 'font-family:Russo One,sans-serif;font-size:14px;padding:2px 8px;border:2px solid #141414;background:' + (TAGC[a.dist] || '#ffd60a') + ';color:' + (a.dist === 'factory' || a.dist === 'web' || a.dist === 'base' ? '#141414' : '#ffffff'),
      coverStyle: 'position:relative;aspect-ratio:4/5;overflow:hidden;border-bottom:3px solid #141414;background-color:' + a.color
    }));

    const user = window.CC ? CC.getUser() : null;
