      slideItem, dots,
      flipA: (st.flips || 0) % 2 === 0, flipB: (st.flips || 0) % 2 === 1,
      turnCls: st.flips ? (st.dir === 'p' ? 'cc-turnP' : 'cc-turnN') : '',
